  // Block 2: counts per Park_Clean, all rows vs. Final rows (starts two rows below block 1)
  const allCounts = {};
  const finalCounts = {};
  recs.forEach(r => { allCounts[r.park] = (allCounts[r.park] || 0) + 1; });
  finalRecs.forEach(r => { finalCounts[r.park] = (finalCounts[r.park] || 0) + 1; });

  const parks = Object.keys(allCounts).sort((a, b) => {
    if (a === 'REVIEW') return 1;                                   // unmapped bucket goes last
    if (b === 'REVIEW') return -1;
    return allCounts[b] - allCounts[a] || a.localeCompare(b);       // then by count desc, name asc
  });

  const parkRows = [['Park_Clean', 'All rows', 'Final rows']]
    .concat(parks.map(p => [safeText_(p), allCounts[p], finalCounts[p] || 0]));
  const startRow = overall.length + 2;
  sh.getRange(startRow, 1, parkRows.length, 3).setValues(parkRows);
  sh.getRange(startRow, 1, 1, 3).setFontWeight('bold');

  sh.setFrozenRows(1);
  sh.autoResizeColumns(1, 3);
}

// ===================== NORMALIZATION HELPERS =====================

function normalizeYesNo_(v) {
  const s = String(v).trim().toLowerCase();
  if (!s) return 'REVIEW';
  if (CONFIG.YES_VALUES.includes(s)) return 'Yes';
  if (CONFIG.NO_VALUES.includes(s)) return 'No';
  return 'REVIEW';
}

function normalizePhone_(v) {
  let d = String(v).replace(/\D/g, '');
  if (!d) return 'REVIEW';
  const cc = CONFIG.PHONE_COUNTRY_CODE;
  if (cc && d.length === CONFIG.PHONE_LENGTH + cc.length && d.startsWith(cc)) {
    d = d.slice(cc.length);
  }
  const ac = CONFIG.DEFAULT_AREA_CODE;
  if (ac && d.length + ac.length === CONFIG.PHONE_LENGTH) d = ac + d;
  return d.length === CONFIG.PHONE_LENGTH ? d : 'REVIEW';
}

function parkKey_(v) {
  return String(v).toLowerCase().replace(/[^a-z]/g, '');
}

function loadParkMap_(ss) {
  const sh = ss.getSheetByName(CONFIG.PARKMAP_SHEET);
  if (!sh) throw new Error('Sheet "' + CONFIG.PARKMAP_SHEET + '" not found (Col A = variant, Col B = canonical).');
  const map = {};
  sh.getDataRange().getValues().forEach((row, idx) => {
    if (idx === 0 && String(row[0]).trim().toLowerCase() === 'key') return;   // skip header row
    const variant = parkKey_(row[0]);
    const canonical = String(row[1] || '').trim();
    if (!variant || !canonical) return;
    map[variant] = canonical;
    const selfKey = parkKey_(canonical);                                       // canonical maps to itself
    if (selfKey && !map[selfKey]) map[selfKey] = canonical;
  });
  return map;
}

function mapPark_(v, map) {
  const key = parkKey_(v);
  if (!key) return 'REVIEW';
  return map[key] || 'REVIEW';   // Unmapped -> REVIEW; add the variant to ParkMap and re-run
}

// Returns a valid Date or null. Handles real date cells, "4/3/2021 09:12", "04-03-21",
// "2021-04-03 14:01", "03-Mar-2021", "3 Mar 2021", "Mar 3, 2021", with optional time and am/pm.
function parseTimestamp_(v) {
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v;
  const s = String(v).trim().toLowerCase();
  if (!s) return null;

  let y, m, d, rest;
  let mt;
  if ((mt = s.match(/^(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})(.*)$/))) {              // Y-M-D
    y = +mt[1]; m = +mt[2]; d = +mt[3]; rest = mt[4];
  } else if ((mt = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})(.*)$/))) {     // M/D/Y or D/M/Y
    const a = +mt[1], b = +mt[2];
    if (CONFIG.DATE_ORDER === 'DMY') { d = a; m = b; } else { m = a; d = b; }
    y = +mt[3]; rest = mt[4];
  } else if ((mt = s.match(/^(\d{1,2})[\s\-\/]+([a-z]{3,})\.?[\s\-\/,]+(\d{2,4})(.*)$/))) {  // 03-Mar-2021
    d = +mt[1]; m = monthIndex_(mt[2]); y = +mt[3]; rest = mt[4];
  } else if ((mt = s.match(/^([a-z]{3,})\.?\s+(\d{1,2}),?\s+(\d{2,4})(.*)$/))) {            // Mar 3, 2021
    m = monthIndex_(mt[1]); d = +mt[2]; y = +mt[3]; rest = mt[4];
  } else {
    return null;
  }
  if (!m) return null;
  if (y < 100) y += (y < 70 ? 2000 : 1900);

  let h = 0, mi = 0, sec = 0;
  const tm = (rest || '').match(/(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(am|pm)?/);
  if (tm) {
    h = +tm[1]; mi = +tm[2]; sec = tm[3] ? +tm[3] : 0;
    if (tm[4] === 'pm' && h < 12) h += 12;
    if (tm[4] === 'am' && h === 12) h = 0;
    if (h > 23 || mi > 59 || sec > 59) return null;
  } else if ((rest || '').trim()) {
    return null;                                    // unexpected trailing text -> REVIEW
  }

  const dt = new Date(y, m - 1, d, h, mi, sec);
  if (dt.getFullYear() !== y || dt.getMonth() !== m - 1 || dt.getDate() !== d) return null;  // e.g. 2/30
  return dt;
}

function monthIndex_(name) {
  const i = MONTHS.indexOf(String(name).slice(0, 3).toLowerCase());
  return i === -1 ? 0 : i + 1;
}

// Prevents text like "+1 555 1236" or "=..." from being interpreted as a formula when written back.
function safeText_(v) {
  if (typeof v !== 'string') return v;
  return /^[=+\-@]/.test(v) ? "'" + v : v;
}
